"""Pin BSM bootstrap environment without exposing database credentials in units."""

import json
import os
import stat
import tempfile
from pathlib import Path

from .checkpoint_files import sync_directory
from .config import Config


def contents(config: Config) -> str:
    """Render systemd EnvironmentFile values with literal double-quote escaping."""
    values = {}
    if config.bsm_db_url is not None:
        values["BSM_DB_URL"] = config.bsm_db_url
    if config.bsm_log_level is not None:
        values["BSM_LOG_LEVEL"] = config.bsm_log_level
    return (
        "# Generated by bsm-supervisor; regenerate while BSM is stopped.\n"
        + "".join(
            key + "=" + json.dumps(value, ensure_ascii=False) + "\n"
            for key, value in values.items()
        )
    )


def write_environment(config: Config) -> None:
    """Publish private startup values; systemd reads them before dropping user."""
    config.state_dir.mkdir(mode=0o700, parents=True, exist_ok=True)
    path = config.state_dir / "bsm-runtime.env"
    descriptor, name = tempfile.mkstemp(prefix=".bsm-runtime-", dir=config.state_dir)
    temporary = Path(name)
    try:
        with os.fdopen(descriptor, "w") as stream:
            stream.write(contents(config))
            stream.flush()
            os.fsync(stream.fileno())
        os.replace(temporary, path)
        sync_directory(config.state_dir)
    finally:
        temporary.unlink(missing_ok=True)


def verify_environment(config: Config) -> None:
    """Reject drift before filesystem/database maintenance; never echo secrets."""
    path = config.state_dir / "bsm-runtime.env"
    try:
        info = path.lstat()
        if (
            not stat.S_ISREG(info.st_mode)
            or info.st_mode & 0o077
            or info.st_size > 65536
        ):
            raise ValueError("Invalid managed environment file permissions")
        if path.read_text() != contents(config):
            raise ValueError(
                "Managed environment changed; regenerate it while BSM is stopped"
            )
    except FileNotFoundError as exc:
        raise ValueError(
            "Generate the managed service environment before maintenance"
        ) from exc
